package com.smritisathi.app.auth;
import android.content.*;import android.os.*;import android.widget.*;import com.google.gson.*;import com.smritisathi.app.PatientDashboardActivity;import com.smritisathi.app.caregiver.CaregiverPatientListActivity;import com.smritisathi.app.core.*;
public class LoginActivity extends BaseActivity { EditText phone,password; @Override public void onCreate(Bundle b){super.onCreate(b); if(!Session.token(this).isEmpty()){go();return;} header("Smriti Sathi");root.addView(UI.text(this,"Welcome back. Sign in to continue."));phone=UI.edit(this,"Phone number");password=UI.edit(this,"Password");password.setInputType(0x81);root.addView(phone);root.addView(password);Button login=UI.button(this,"Login");root.addView(login);Button reg=UI.button(this,"Create a new account");root.addView(reg);login.setOnClickListener(v->login());reg.setOnClickListener(v->startActivity(new Intent(this,RegisterActivity.class)));} void login(){if(phone.getText().length()==0||password.getText().length()==0){UI.toast(this,"Please enter phone and password");return;} JsonObject body=UIObj("phone",phone.getText().toString(),"password",password.getText().toString());ApiClient.request("POST","/auth/login",null,body,(ok,d,e)->{if(!ok){UI.toast(this,e);return;}JsonObject u=d.getAsJsonObject("user");Session.save(this,d.get("token").getAsString(),u.get("role").getAsString(),u.get("_id").getAsString(),u.get("name").getAsString(),u.has("preferredLanguage")?u.get("preferredLanguage").getAsString():"english");go();});} JsonObject UIObj(Object...x){return ApiClient.obj(x);} void go(){if("caregiver".equals(Session.role(this)))startActivity(new Intent(this,CaregiverPatientListActivity.class));else startActivity(new Intent(this,PatientDashboardActivity.class));finish();}}
